"""Which faces painted each record's glyphs, per weight: the Japanese display's records here, beside the English (United
Kingdom) display's records of the seventeenth run in tests/GlyphWidths/. Writes painters.md.

    python3 painters.py
"""
import collections
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
TESTS = os.path.join(HERE, '..', '..', 'tests', 'GlyphWidths')
out = ['# The faces that painted each record, per weight', '',
       'Generated by `painters.py`: each record\'s `painters`, the faces Chrome or Edge reported for each glyph '
       '(`CSS.getPlatformFontsForNode`), counted. "en-GB" is the seventeenth run\'s record in `tests/GlyphWidths/`, '
       '"ja" this run\'s in `glyphs/`.', '']
for face in ('system-ui', 'roboto'):
    for browser in ('chrome', 'msedge'):
        ja = json.load(open(os.path.join(HERE, 'glyphs', f'{face}.windows-ja.{browser}.json'), encoding='utf-8'))
        en = json.load(open(os.path.join(TESTS, f'{face}.windows.{browser}.json'), encoding='utf-8'))
        out += [f'## `{face}` in {"Chrome" if browser == "chrome" else "Edge"}', '',
                f'- {len(ja["glyphs"])} glyphs, {ja["corpus"]} strings; the corpus\'s hash in the record, '
                f'`{ja["corpusSha256"][:16]}…`, {"the same as" if ja["corpusSha256"] == en["corpusSha256"] else "**not** the same as"} '
                f'the English record\'s.', '', '| Weight | en-GB display | ja display |', '|---|---|---|']
        for w in ('400', '500', '600', '700'):
            def counted(r):
                c = collections.Counter(r['painters'][w])
                return '; '.join(f'{k} {n}' for k, n in c.most_common())
            out.append(f'| {w} | {counted(en)} | {counted(ja)} |')
        # The glyphs whose face changed with the display language, at 400.
        changed = [(g, a, b) for g, a, b in zip(ja['glyphs'], en['painters']['400'], ja['painters']['400']) if a != b] \
            if ja['glyphs'] == en['glyphs'] else None
        if changed is None:
            out += ['', '- The two records do not hold the same glyphs, so they are not compared glyph by glyph.', '']
        else:
            out += ['', f'- At 400, {len(changed)} of {len(ja["glyphs"])} glyphs were painted by another face under the '
                        f'Japanese display.', '']
            byPair = collections.Counter((a, b) for g, a, b in changed)
            for (a, b), n in byPair.most_common():
                sample = ''.join(g for g, x, y in changed if (x, y) == (a, b))[:40]
                out.append(f'  - {a} → {b}: {n} (`{sample}`)')
            out.append('')
open(os.path.join(HERE, 'painters.md'), 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print('\n'.join(out))
